package com.rpb.reservation.workforce.statutory;
import static com.rpb.reservation.workforce.statutory.StatutoryPolicyConfig.*;import static com.rpb.reservation.workforce.statutory.StatutoryPolicies.*;import com.rpb.reservation.workforce.domain.WorkforceException;import java.time.*;import java.util.*;
/** Official starting data only. Production calculations resolve saved tenant policy revisions. */
public final class OfficialStatutoryTemplates {
 private OfficialStatutoryTemplates(){}
 public static Template forYear(int year){if(year!=2026&&year!=2027)throw WorkforceException.missing();var ages=List.of(new AgeBand("55_AND_BELOW","55岁及以下",55),new AgeBand("ABOVE_55_TO_60","55岁以上至60岁",60),new AgeBand("ABOVE_60_TO_65","60岁以上至65岁",65),new AgeBand("ABOVE_65_TO_70","65岁以上至70岁",70),new AgeBand("ABOVE_70","70岁以上",null));String[] fullEr=year==2026?new String[]{"0.17","0.16","0.125","0.09","0.075"}:new String[]{"0.17","0.165","0.13","0.09","0.075"},fullEe=year==2026?new String[]{"0.20","0.18","0.125","0.075","0.05"}:new String[]{"0.20","0.19","0.13","0.075","0.05"},firstEr={"0.04","0.04","0.035","0.035","0.035"},firstEe={"0.05","0.05","0.05","0.05","0.05"},secondEr={"0.09","0.06","0.035","0.035","0.035"},secondEe={"0.15","0.125","0.075","0.05","0.05"};
  var tables=List.of(table("T1","公民／SPR第3年起及已批准F/F",ages,fullEr,fullEe),table("T2","SPR第1年 G/G",ages,firstEr,firstEe),table("T3","SPR第2年 G/G",ages,secondEr,secondEe),table("T4","SPR第1年 已批准F/G",ages,fullEr,firstEe),table("T5","SPR第2年 已批准F/G",ages,fullEr,secondEe));var wages=List.of(new WageBand("ZERO","50及以下","50","none","0"),new WageBand("EMPLOYER_ONLY","50以上至500","500","employer_only","0"),new WageBand("RAMP","500以上至750","750","ramp","3"),new WageBand("NORMAL","750以上",null,"normal","0"));var config=new StatutoryPolicyConfig(1,"8000",ages,wages,tables,new Sdl("0.0025","2","11.25"),"HALF_UP","FLOOR","FLOOR",year==2026?"https://www.cpf.gov.sg/content/dam/web/employer/employer-obligations/documents/CPFcontributionratesfrom1Jan2026.pdf":"https://www.cpf.gov.sg/content/dam/web/employer/employer-obligations/documents/jan2027cpfcontributionrates.pdf","https://www.cpf.gov.sg/employer/employer-obligations/skills-development-levy","next_month","next_month","新加坡私营机构普通工资。生日及SPR周年次月生效；月中取得SPR、AW/AWS和跨期补缴须另行处理。");return new Template(year+"年新加坡CPF／SDL普通工资",year,"SGD",LocalDate.of(year,1,1),LocalDate.of(year,12,31),config.withCdac(CdacRules.official(year)));
 }
 private static Table table(String code,String name,List<AgeBand> ages,String[] er,String[] ee){var rates=new ArrayList<Rate>();for(int i=0;i<ages.size();i++)rates.add(new Rate(ages.get(i).code(),er[i],ee[i]));return new Table(code,name,List.copyOf(rates));}
 public static Template forYearWithAw(int year){var old=forYear(year);return new Template(year+" CPF/SDL OW+AW",year,old.currency(),old.effectiveFrom(),old.effectiveTo(),old.config().withNotes("新加坡私营机构OW与AW合并月度CPF；AW须有完整年度额度依据。生日及SPR周年次月生效；月中取得SPR及低工资渐进档AW截限情形仍须另行核实。跨期补缴沿用原期费率复核，不通过普通月度事项处理。").withAw(new AwCapability("102000","SG-OW-AW-MONTH-v2","https://www.cpf.gov.sg/service/article/what-is-the-additional-wage-aw-ceiling")));}
 public static boolean legacy2026(Policy p){return p!=null&&p.version()==1&&p.year()==2026&&p.currency().equals("SGD")&&p.effectiveFrom().equals(LocalDate.of(2026,1,1))&&p.effectiveTo().equals(LocalDate.of(2026,12,31))&&p.config().equals(forYear(2026).config());}
}
